use verus::prelude::*;

verus! {
    /// Swap the first and last element of a non‐empty Vec<i32> in place.
    ///
    /// Requires:
    ///     - The vector is non‐empty.
    ///
    /// Ensures:
    ///     - The length is unchanged.
    ///     - The new first element equals the old last element.
    ///     - The new last element equals the old first element.
    ///     - Every element strictly between first and last is unchanged.
    fn swap_first_and_last(a: &mut Vec<i32>)
        requires
            a.len() > 0,
        ensures
            // length is preserved
            a.len() == old(a.len()),
        ensures
            // first becomes old last
            a[0] == old(|h| h[a][old(a.len()) - 1]),
        ensures
            // last becomes old first
            a[a.len() - 1] == old(|h| h[a][0]),
        ensures
            // all middle elements are unchanged
            forall |i: usize|
                1 <= i && i < a.len() - 1 ==>
                a[i] == old(|h| h[a][i]),
    {
        // compute last index
        let last = a.len() - 1;
        // Rust’s built‐in swap
        a.swap(0, last);

        // Optional re‐assertions to help the verifier close all goals:
        assert(a.len() == old(a.len()));
        assert(a[0] == old(|h| h[a][last]));
        assert(a[last] == old(|h| h[a][0]));
        assert(forall|i: usize| 1 <= i && i < a.len() - 1 ==> a[i] == old(|h| h[a][i]));
    }
}

